const tankPhoto=new Image();tankPhoto.src=new URL('./assets/tank-photoreal.png',import.meta.url).href;tankPhoto.onload=()=>window.dispatchEvent(new Event('artillery-assets-loaded'));const pinePhoto=new Image();pinePhoto.src=new URL('./assets/pine-photoreal.png',import.meta.url).href;pinePhoto.onload=()=>window.dispatchEvent(new Event('artillery-assets-loaded'));
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function line(c,points){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.stroke();}
function sky(c,wind=0,time=0){const bg=c.createLinearGradient(0,0,0,H);bg.addColorStop(0,'#142536');bg.addColorStop(.48,'#566f7b');bg.addColorStop(.88,'#d0a986');bg.addColorStop(1,'#e3b48a');c.fillStyle=bg;c.fillRect(0,0,W,H);const sun=c.createRadialGradient(750,230,5,750,230,200);sun.addColorStop(0,'#f8d8a593');sun.addColorStop(1,'#f8d8a500');c.fillStyle=sun;c.fillRect(500,10,460,420);for(let layer=0;layer<3;layer++){c.fillStyle=['#84919255','#586d7366','#394f5866'][layer];c.beginPath();c.moveTo(0,390);for(let x=0;x<=W;x+=8)c.lineTo(x,330+layer*26+20*Math.sin(x/(60+layer*20)+layer*2)+10*Math.sin(x/27+layer));c.lineTo(W,H);c.lineTo(0,H);c.fill();}for(let i=0;i<6;i++){const drift=wind*time*(2.3+i%3*.6),x=((i*179+60+drift+220)%(W+440)+(W+440))%(W+440)-220,y=80+(i%3)*31;c.fillStyle='#e4dfd42b';c.beginPath();c.ellipse(x,y,90,13,-.05,0,Math.PI*2);c.fill();c.beginPath();c.ellipse(x-32,y-7,49,9,-.08,0,Math.PI*2);c.fill();}}
function ground(c,g,seed,round){c.save();c.beginPath();c.moveTo(0,H);c.lineTo(0,g[0]);for(let x=1;x<W;x+=2)c.lineTo(x,g[x]);c.lineTo(W,H);c.closePath();c.clip();const dirt=c.createLinearGradient(0,310,0,H);dirt.addColorStop(0,'#6d7458');dirt.addColorStop(.25,'#5c5946');dirt.addColorStop(1,'#292f32');c.fillStyle=dirt;c.fillRect(0,0,W,H);for(let x=0;x<W;x+=4)if(materialAt(seed,round,x)==='rock'){const edge=g[x];const stone=c.createLinearGradient(0,edge,0,edge+170);stone.addColorStop(0,'#9a9d96');stone.addColorStop(.36,'#6c7371');stone.addColorStop(.72,'#444d4eb8');stone.addColorStop(1,'#444d4e00');c.fillStyle=stone;c.fillRect(x,edge,4,170);c.fillStyle='#d1d0bf30';c.fillRect(x,edge+7+(x%17),4,1);if(x%20===0){c.strokeStyle='#353f4270';c.lineWidth=1;c.beginPath();c.moveTo(x,edge+30);c.lineTo(x+14,edge+45);c.stroke();}}for(let i=0;i<1200;i++){const x=(i*457.7)%W,y=315+(i*173.3)%(H-315),v=i%5;c.fillStyle=v===0?'#d4c39a30':v===1?'#1d24252b':'#7e817433';c.fillRect(x,y,1+v%3,1+v%2);}c.restore();for(let x=2;x<W-2;x+=3){const y=g[x],rock=materialAt(seed,round,x)==='rock';c.fillStyle=rock?'#a9aca5':'#789660';c.fillRect(x,y-1,3,rock?2:3);}for(let x=13;x<W;x+=17){if(materialAt(seed,round,x)==='rock')continue;const y=g[x];c.strokeStyle=x%3?'#73935caa':'#9aaf73aa';c.lineWidth=1.2;c.beginPath();c.moveTo(x,y);c.lineTo(x-2-(x%5),y-4-(x%3));c.moveTo(x,y);c.lineTo(x+2,y-3-(x%4));c.stroke();}}
function landscapeDetails(c,g,seed,round,time,wind){
 const base=(seed+round*7919)>>>0,original=terrain(round===1?seed:base);
 for(let n=0;n<13;n++){const x=55+((Math.imul(n+13,1973)+base)%850),y=g[x];if(x<43||x>W-43)continue;
  const size=5+(n%4)*2;c.save();c.translate(x,y-1);c.fillStyle='#2a3030aa';c.beginPath();c.ellipse(1,2,size+2,3,0,0,7);c.fill();const stone=c.createLinearGradient(-size,-size,size,size);stone.addColorStop(0,'#aaa894');stone.addColorStop(.45,'#6f756b');stone.addColorStop(1,'#353d3d');c.fillStyle=stone;c.beginPath();c.moveTo(-size,0);c.lineTo(-size*.8,-size*.65);c.lineTo(-size*.2,-size);c.lineTo(size*.65,-size*.72);c.lineTo(size,0);c.closePath();c.fill();c.strokeStyle='#d8d4bb77';c.lineWidth=1;c.beginPath();c.moveTo(-size*.7,-size*.55);c.lineTo(-size*.2,-size*.87);c.lineTo(size*.45,-size*.65);c.stroke();c.restore();}
 for(let n=0;n<9;n++){const x=76+((Math.imul(n+7,6131)+base)%800),y=g[x],height=49+n%4*11;if(x<55||x>W-55||Math.abs(x-105)<67||Math.abs(x-855)<67||y>H-35||y-original[x]>10||materialAt(seed,round,x)==='rock')continue;c.save();c.translate(x,y);c.rotate((wind*.004)+Math.sin(time*2.1+n*.8)*(.012+Math.abs(wind)*.003));c.fillStyle='#232a29aa';c.beginPath();c.ellipse(2,2,13,3,0,0,7);c.fill();if(pinePhoto.complete&&pinePhoto.naturalWidth){c.drawImage(pinePhoto,-height*.34,-height,height*.68,height+5);c.restore();continue;}c.fillStyle='#574735';c.fillRect(-2,-height,4,height);c.fillStyle='#92795b';c.fillRect(-1,-height,1,height);for(let tier=0;tier<4;tier++){const cy=-height+5+tier*height*.19,wide=(4-tier)*3+3;const crown=c.createLinearGradient(-wide,cy,wide,cy);crown.addColorStop(0,'#223c35');crown.addColorStop(.42,'#5d7350');crown.addColorStop(1,'#1f3935');c.fillStyle=crown;c.beginPath();c.moveTo(0,cy-height*.22);c.lineTo(-wide,cy+height*.11);c.lineTo(wide,cy+height*.11);c.closePath();c.fill();}c.restore();}
}
function windFlag(c,g,wind,time){const x=475,y=g[x]-2,dir=wind===0?1:Math.sign(wind),length=18+Math.abs(wind)*3,wave=Math.sin(time*(4+Math.abs(wind)*.5))*Math.min(8,2+Math.abs(wind));c.save();c.strokeStyle='#282d2b';c.lineWidth=4;c.beginPath();c.moveTo(x,y);c.lineTo(x,y-72);c.stroke();c.strokeStyle='#c9c1a5';c.lineWidth=2;c.beginPath();c.moveTo(x-1,y);c.lineTo(x-1,y-72);c.stroke();c.fillStyle='#4b3730';c.beginPath();c.ellipse(x,y,8,3,0,0,7);c.fill();c.fillStyle=wind===0?'#d8c8a1':'#e5a369';c.beginPath();c.moveTo(x,y-70);c.bezierCurveTo(x+dir*length*.32,y-75,x+dir*length*.6,y-64,x+dir*length,y-69+wave);c.lineTo(x+dir*length*.88,y-54+wave*.6);c.bezierCurveTo(x+dir*length*.4,y-61,x+dir*length*.22,y-54,x,y-57);c.closePath();c.fill();c.strokeStyle='#f3d6a99c';c.lineWidth=1;c.stroke();c.fillStyle='#f8e8ce';c.font='bold 13px system-ui';c.textAlign='center';c.fillText('VIND '+(wind<0?'←':wind>0?'→':'·')+' '+Math.abs(wind),x,y-81);c.restore();}
function hull(c,p,index){c.save();c.translate(p.x,p.y);c.rotate(p.rotation||0);const base=index?'#8c6259':'#657667',light=index?'#b18a75':'#a0aa91',dark=index?'#423c3a':'#313b3a';c.fillStyle='#13202480';c.beginPath();c.ellipse(0,12,27,5,0,0,7);c.fill();c.fillStyle=dark;c.beginPath();c.roundRect(-24,-4,48,18,8);c.fill();for(let i=-2;i<=2;i++){c.fillStyle='#202726';c.beginPath();c.arc(i*10,6,6.5,0,7);c.fill();c.fillStyle='#85877b';c.beginPath();c.arc(i*10,6,3.4,0,7);c.fill();c.fillStyle='#343a37';c.beginPath();c.arc(i*10,6,1.5,0,7);c.fill();}const grad=c.createLinearGradient(0,-17,0,4);grad.addColorStop(0,light);grad.addColorStop(.55,base);grad.addColorStop(1,dark);c.fillStyle=grad;c.beginPath();c.moveTo(-22,-4);c.lineTo(-17,-14);c.lineTo(14,-14);c.lineTo(23,-6);c.lineTo(22,1);c.lineTo(-22,1);c.closePath();c.fill();c.strokeStyle='#d5d0b166';c.lineWidth=1;c.stroke();c.fillStyle='#242d2d';c.fillRect(-11,-12,8,4);c.fillRect(5,-12,7,3);c.fillStyle='#ddd2aa88';for(const x of [-16,-9,11,17])c.fillRect(x,-3,1,2);c.restore();}
function turret(c,p,index,dir){const base=index?'#8e6b5e':'#718474',light=index?'#cfab89':'#bbbea1';c.save();c.translate(p.x,p.y);c.rotate(p.rotation||0);const t=c.createLinearGradient(0,-28,0,-10);t.addColorStop(0,light);t.addColorStop(1,base);c.fillStyle=t;c.beginPath();c.moveTo(-12,-14);c.lineTo(-9,-24);c.lineTo(3,-28);c.lineTo(13,-23);c.lineTo(15,-14);c.closePath();c.fill();c.strokeStyle='#2c3736';c.lineWidth=1;c.stroke();c.fillStyle='#293535';c.fillRect(-3,-26,5,3);c.restore();const angle=p.angle*Math.PI/180,sx=p.x,sy=p.y-18,ex=sx+dir*34*Math.cos(angle),ey=sy-34*Math.sin(angle);c.strokeStyle='#1e2a2d';c.lineWidth=11;c.lineCap='round';line(c,[[sx,sy],[ex,ey]]);c.strokeStyle=light;c.lineWidth=7;line(c,[[sx,sy],[ex,ey]]);c.strokeStyle='#e4d1a4aa';c.lineWidth=1.5;line(c,[[sx,sy-2],[ex,ey-2]]);c.fillStyle='#2a302d';c.beginPath();c.arc(ex,ey,4.5,0,7);c.fill();c.fillStyle='#e7c498';c.beginPath();c.arc(ex,ey,2,0,7);c.fill();}
function tank(c,p,index,dir){c.save();c.fillStyle='#101d2299';c.beginPath();c.ellipse(p.x,p.y+15,39,5,0,0,7);c.fill();if(tankPhoto.complete&&tankPhoto.naturalWidth){c.translate(p.x,p.y);c.rotate(p.rotation||0);c.scale(dir,1);c.drawImage(tankPhoto,0,410,1536,614,-36,-16,72,40);c.restore();c.save();c.translate(p.x,p.y-17);c.scale(dir,1);c.rotate(-p.angle*Math.PI/180);c.drawImage(tankPhoto,300,45,1236,365,-17,-13,76,23);c.restore();c.fillStyle=index?'#e18e77':'#90d0b4';c.fillRect(p.x-5,p.y+17,10,3);}else{hull(c,p,index);turret(c,p,index,dir);c.restore();}}
function shell(c,x,y,a){c.save();c.translate(x,y);c.rotate(a);c.shadowColor='#ffd88b';c.shadowBlur=14;c.fillStyle='#d9b785';c.beginPath();c.moveTo(10,0);c.lineTo(2,-3.5);c.lineTo(-9,-3.2);c.lineTo(-9,3.2);c.lineTo(2,3.5);c.closePath();c.fill();c.fillStyle='#6b4934';c.fillRect(-9,-3.2,3,6.4);c.strokeStyle='#fff0c7';c.lineWidth=1;c.beginPath();c.moveTo(0,-2);c.lineTo(7,-.4);c.stroke();c.restore();}
function explosion(c,x,y,step,radius){const k=clamp(step/18,0,1);for(let i=0;i<20;i++){const a=i*2.399,r=(i%5+1)*radius*.15*k,px=x+Math.cos(a)*r,py=y+Math.sin(a)*r-11*k;c.fillStyle=i%3?'#342f2b80':'#d28f5d99';c.beginPath();c.arc(px,py,4+(i%4)*3+step*.28,0,7);c.fill();}const glow=c.createRadialGradient(x,y,2,x,y,radius*k);glow.addColorStop(0,'#fff0bb');glow.addColorStop(.3,'#ffbf66dd');glow.addColorStop(1,'#ff8c2c00');c.fillStyle=glow;c.beginPath();c.arc(x,y,radius*k,0,7);c.fill();}
export function render(c,game,{animation=null,preview=null,aim=null,time=0}={}){sky(c,game?.wind||0,time);if(!game){c.fillStyle='#f0f0e4';c.textAlign='center';c.font='bold 42px system-ui';c.fillText('Klar til kamp?',W/2,235);c.font='20px system-ui';c.fillText('Vælg modstander for at begynde',W/2,275);return;}const flight=animation&&animation.index<animation.path.length,groundData=flight?animation.groundBefore:game.ground;ground(c,groundData,game.seed,game.round);landscapeDetails(c,groundData,game.seed,game.round,time,game.wind);windFlag(c,groundData,game.wind,time);for(let i=0;i<2;i++){const base=game.players[i],motion=animation&&!flight&&animation.motion.length?animation.motion[Math.min(animation.motionIndex,animation.motion.length-1)]?.[i]:null,position=flight?animation.before[i]:motion||base;tank(c,{...base,...position,angle:aim?.player===i&&!animation?aim.angle:base.angle},i,Math.sign(game.players[1-i].x-position.x)||1);}if(animation){const {path,index,hit}=animation;if(flight){c.strokeStyle='#ffe1a47a';c.lineWidth=2;c.setLineDash([5,5]);line(c,path.slice(Math.max(0,index-20),index).map(p=>p.slice(0,2)));c.setLineDash([]);const [x,y,a]=path[Math.min(index,path.length-1)];shell(c,x,y,a);}else explosion(c,hit.x,hit.y,index-path.length,animation.radius);}else if(preview){const t=trace(game,game.turn,preview.angle,preview.power);c.strokeStyle='#d5e4d388';c.lineWidth=1.6;c.setLineDash([2,9]);line(c,t.path.map(p=>p.slice(0,2)));c.setLineDash([]);}}
